十进制转任意进制
string toBase(int n,int base){
    string s="0123456789ABCDEF";
    string res="";
    while(n>0){
        res=s[n%base]+res;
        n/=base;
    }
    return res;
}

任意进制转十进制
int toDecimal(string s,int base){
    int res=0;
    for(int i=0;i<s.size();i++){
        int digit;
        if(s[i]>='0'&&s[i]<='9') digit=s[i]-'0';
        else digit=s[i]-'A'+10;
        res=res*base+digit;
    }
    return res;
}

快速幂
int qpow(int a,int b,int mod){
    int sum=1;
    while(b){
        if(b&1){
            sum=(sum*a)%mod;
        }
        a=(a*a)%mod;
        b>>=1;
    }
    return sum;
}

