快速排序
int a[N];
int quick(int l,int r){
    int p=a[l],i=l,j=r;
    while(i<j){
        while(j>i && a[j]>p) j--;
        while(i<j && a[i]<=p) i++;
        swap(a[i],a[j]);
    }
    swap(a[l],a[j]);
    return j;
}
void quick_sort(int l,int r){
    if(r<=l) return;
    int mid=quick(l,r);
    quick_sort(l,mid-1);
    quick_sort(mid+1,r);
}
signed main(){
    int n;
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>a[i];
    }
    quick_sort(1,n);
    for(int i=1;i<=n;i++){
        cout<<a[i]<<" ";
    }
    return 0;
}

归并排序[逆序对]
问：给定一个整数序列a[N]。逆序对指的是满足i<j且a[i]>a[j]的有序对(I,j)。序列中可能存在相等元素，它们不构成逆序对。请你计算该序列中的逆序对个数，并对1000009取模后输出。
int a[N],b[N];
int ans=0;
void merge(int l,int r){
    int mid=(l+r)/2,i=l,j=mid+1;
    int tot=l;
    while(i<=mid && j<=r){
        if(a[i]<=a[j]) b[tot++]=a[i++];
        else{
            b[tot++]=a[j++];
            ans=(ans+mid-i+1)%mod;
        }
    }
    while(i<=mid) b[tot++]=a[i++];
    while(j<=r) b[tot++]=a[j++];
    for(int i=l;i<=r;i++){
        a[i]=b[i];
    }
}
void merge_sort(int l,int r){
    if(l>=r) return;
    int mid=(l+r)/2;
    merge_sort(l,mid);
    merge_sort(mid+1,r);
    merge(l,r);
}
signed main(){
    int n;
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>a[i];
    }
    merge_sort(1,n);
    cout<<ans%mod;
    return 0;
}

双指针算法[接雨水]
问：给定n个非负整数表示每个宽度为1，高度为a[i] 的柱子，计算按此排列的柱子，下雨之后能接多少水。
int a[N];
signed main(){
    int n;
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>a[i];
    }
    int i=1,j=n,maxi=0,maxj=0;
    int ans=0;
    while(i<j){
        if(a[i]<=a[j]){
            maxi=max(maxi,a[i]);
            if(a[i]<maxi){
                ans+=(maxi-a[i]);
            }
            i++;
        }
        else{
            maxj=max(maxj,a[j]);
            if(a[j]<maxj){
                ans+=(maxj-a[j]);
            }
            j--;
        }
    }
    cout<<ans;
    return 0;
}

