树上搜索[离根最远的距离]
问：给定一棵有n个节点的树，节点编号为1-n。约定将节点1作为根节点。每条边的长度为1。两点之间的距离定义为路径上边的条数。请你计算：从根节点1出发，到所有其他节点的最远距离是多少。
int n,u,v,ans=0;
vector <int> G[200005];
void dfs(int u,int pa,int step){
    ans=max(ans,step);
    for(int i=0;i<G[u].size();i++){
        int uu=u,vv=G[u][i];
        int sstep=step+1;
        if(vv==pa) continue;
        dfs(vv,uu,sstep);
    }
}
struct p{
    int u,pa,step;
};queue <p> q;
void bfs(int u,int pa,int step){
    q.push({u,pa,step});
    while(!q.empty()){
        p now=q.front();
        q.pop();
        ans=max(ans,now.step);
        for(int i=0;i<G[now.u].size();i++){
            int uu=now.u,vv=G[now.u][i];
            int sstep=now.step+1;
            if(vv==now.pa) continue;
            q.push({vv,uu,sstep});
        }
    }
}
signed main(){
    cin>>n;
    for(int i=1;i<n;i++){
        cin>>u>>v;
        G[u].push_back(v);
        G[v].push_back(u);
    }
    dfs(1,0,0);//或bfs(1,0,0);
    cout<<ans;
    return 0;
}

树上搜索[最近公共祖先]
问：给定一棵有根多叉树，请求出指定两个点直接最近的公共祖先。
第一行包含三个正整数n,m,s。分别表示树的结点个数、询问的个数和树根结点的序号。
接下来n-1行每行包含两个正整数 x,y，表示x结点和y结点之间有一条直接连接的边（数据保证可以构成树）。
接下来m行每行包含两个正整数 a,b，表示询问a结点和b结点的最近公共祖先。
vector <int> G[1005];
int n,m,s,u,v,a,b;
int st[1005],p[1005];
void dfs(int u,int pa,int step){
    p[u]=pa;
    st[u]=step;
    for(int i=0;i<G[u].size();i++){
        int v=G[u][i];
        if(v==pa) continue;
        dfs(v,u,step+1);
    }
}
int LAC(int a,int b){
    while(st[a]>st[b]) a=f[a];
    while(st[a]<st[b]) b=f[b];
    while(a!=b){
        a=f[a];
        b=f[b];
    }
    return a;
}
signed main(){
    cin>>n>>m>>s;
    for(int i=1;i<n;i++){
        cin>>u>>v;
        G[u].push_back(v);
        G[v].push_back(u);
    }
    dfs(s,0,0);
    for(int i=1;i<=m;i++){
        cin>>a>>b;
        cout<<LAC(a,b)<<endl;
    }
    return 0;
}

