void add(int a,int b,int c,int d,int x){
    diff[a][b]+=x;
    diff[c+1][b]-=x;
    diff[a][d+1]-=x;
    diff[c+1][d+1]+=x;
}
void restore(int v[][MAXN],int n,int m){
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
