int lowerb(int l,int r,int x){
    while(l<=r){
        int mid=l+(r-l)/2;
        if(a[mid]>=x){
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return l;
}//第一个大于等于x下标
int upperb(int l,int r,int x){
    while(l<=r){
        int mid=l+(r-l)/2;
        if(a[mid]>x){
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return l;
}//第一个大于x的下标

