int mstack(int h){
    int ans=0;
    int prevv[N],nextt[N];
    pii a[N];
    stack <pii> s;
    for(int i=0;i<=m+1;i++){
        if(i==0 || i==m+1){
            a[i].first=0;
        }
        else{
            a[i].first=v[h][i];
        }
        a[i].second=i;
    }
    while(!s.empty()) s.pop();
    for(int i=0;i<=m+1;i++){
        while(!s.empty() && a[i].first<s.top().first){
            nextt[s.top().second]=i;
            s.pop();
        }
        if(!s.empty()){
            if(a[i].first==s.top().first){
                prevv[i]=prevv[s.top().second];
            }
            else{
                prevv[i]=s.top().second;
            }
        }
        s.push(a[i]);
    }
    for(int i=1;i<=m;i++){
        ans=max(ans,(nextt[i]-prevv[i]-1)*a[i].first);
    }
    return ans;
}
