void merge(int u,int v){
    int ru=find(u),rv=find(v);
    if(ru==rv){
        s.push({-1,-1,-1,-1});
        cout<<mx[ru]<<endl;
        return ;
    }
    if(sz[ru]<sz[rv]){
        swap(ru,rv);
    }
    s.push({ru,rv,mx[ru],sz[ru]});
    pa[rv]=ru;
    mx[ru]=max(mx[ru],mx[rv]);
    sz[ru]+=sz[rv];
    cout<<mx[ru]<<endl;
}
void ctrlz(){
    if(s.empty()) return ;
    BCJ p=s.top();
    s.pop();
    if(p.pu==-1) return ;
    pa[p.pv]=p.pv;
    mx[p.pu]=p.old_mx;
    sz[p.pu]=p.old_sz;
}
signed main(){
