        if(find(x)==find(y+n)){
            cout<<"contradiction"<<endl;
        }
        else{
            merge(x,y);
            merge(x+n,y+n);
        }
    }
    if(q==2){
        if(find(x)==find(y)){
            cout<<"contradiction"<<endl;
        }
        else{
            merge(x,y+n);
            merge(x+n,y);
        }
    }
}
void print(int x,int y){
    if(find(x)==find(y)){
        cout<<"friend"<<endl;
    }
    else if(find(x)==find(y+n)){
        cout<<"enemy"<<endl;
    }
    else{
        cout<<"no relationship"<<endl;
    }
}
