逆序对
问：对于给定的一段有理数序列，逆序对就是序列中a[i]>a[j]且i<j的有序对。给定的一段有理数序列，算出逆序对的数目。注意序列中可能有重复数字。
int n,tot,ans=0;
double a[N],b[N],c[N];
void add(int i,int k){
    while(i<=tot){
        c[i]+=k;
        i+=lowbit(i);
    }
}
int sum(int i){
    int s=0;
    while(i){
        s+=c[i];
        i-=lowbit(i);
    }
    return s;
}
signed main(){
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>a[i];
        b[i]=a[i];
    }
    sort(b+1,b+n+1);
    tot=unique(b+1,b+n+1)-(b+1);
    for(int i=1;i<=n;i++){
        int t=lowerb(1,tot,a[i]);// >
        add(t,1);
        ans=(ans+sum(tot)-sum(t))%mod;
    }
    cout<<ans;
