}

区间和
问：第一行包含一个整数n，表示该数列数字的个数。第二行包含n个用空格分隔的整数，其中第i个数字表示数列第i项的初始值。第三行包含个一整数m，表示有m次操作个数。接下来m行，每行表示一个操作，具体如下：
[op x y]表示将区间[l,r]中的每个数开方并且向下取整；
[op x y]输出区间[l,r]中每个数的和。
数据中可能有l>r，此时你需要交换它们。
struct node{
    int l,r,sum;
};
int n,m,op,x,y;
int a[N];
node tree[4*N];
void pushup(int root){
    tree[root].sum=tree[root*2].sum+tree[root*2+1].sum;
}
void build(int root,int l,int r){
    tree[root].l=l;
    tree[root].r=r;
    if(l==r){
        tree[root].sum=a[l];
        return ;
    }
    int mid=l+r>>1;
    build(root*2,l,mid);
    build(root*2+1,mid+1,r);
    pushup(root);
}
void updata(int root,int l,int r){
    if(tree[root].l==tree[root].r){
        tree[root].sum=sqrt(tree[root].sum);
        return ;
    }
    if(tree[root].r-tree[root].l+1==tree[root].sum){
        return ;
    }
    int mid=tree[root].l+tree[root].r>>1;
    if(l<=mid) updata(root*2,l,r);
    if(r>mid) updata(root*2+1,l,r);
    pushup(root);
}
int query(int root,int l,int r){
    if(l<=tree[root].l && tree[root].r<=r){
        return tree[root].sum;
    }
    int mid=tree[root].l+tree[root].r>>1;
    int m=0;
    if(l<=mid) m+=query(root*2,l,r);
    if(r>mid) m+=query(root*2+1,l,r);
    return m;
}
signed main(){
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>a[i];
    }
    build(1,1,n);
    cin>>m;
    while(m--){
        cin>>op>>x>>y;
        if(x>y) swap(x,y);
        if(op==0){
            updata(1,x,y);
        }
        if(op==1){
            cout<<query(1,x,y)<<endl;
        }
    }
    return 0;
}

乘加lazy标记
问：第一行包含三个整数n,q,m，分别表示该数列数字的个数、操作的总个数和模数。第二行包含n个用空格分隔的整数，其中第i个数字表示数列第i项的初始值。接下来q行，每行表示一个操作，具体如下：
[1 x y k]含义：将区间[x,y]内每个数乘上；
[2 x y k]含义：将区间[x,y]内每个数加上；
[3 x y]含义：输出区间[x,y]内每个数的和对m取模所得的结果。
struct node{
    int l,r,date;
    int mul=1,add=0;
};
const int N=1e5+5;
int n,q,m;
int op,l,r,x;
int a[N];
node tree[4*N];
void pushup(int root){
    tree[root].date=(tree[root*2].date+tree[root*2+1].date)%m;
}
void Lazy(int root,int mul,int add){
    tree[root].mul=(tree[root].mul*mul)%m;
    tree[root].add=(tree[root].add*mul+add)%m;
    int len=tree[root].r-tree[root].l+1;
    tree[root].date=((tree[root].date*mul)+(len*add))%m;
}
void pushdown(int root){
    Lazy(root*2,tree[root].mul,tree[root].add);
    Lazy(root*2+1,tree[root].mul,tree[root].add);
    tree[root].mul=1;
    tree[root].add=0;
}
void build(int root,int l,int r){
    tree[root].l=l;
    tree[root].r=r;
    if(l==r){
        tree[root].date=a[l];
        return ;
    }
    int mid=l+r>>1;
    build(root*2,l,mid);
    build(root*2+1,mid+1,r);
    pushup(root);
}
void update(int root,int l,int r,int mul,int add){
    if(l<=tree[root].l && tree[root].r<=r){
        Lazy(root,mul,add);
        return ;
    }
    pushdown(root);
    int mid=tree[root].l+tree[root].r>>1;
    if(l<=mid) update(root*2,l,r,mul,add);
    if(r>mid) update(root*2+1,l,r,mul,add);
    pushup(root);
}
int query(int root,int l,int r){
    if(l<=tree[root].l && tree[root].r<=r){
        return tree[root].date;
    }
    pushdown(root);
    int mid=tree[root].l+tree[root].r>>1;
    int ans=0;
    if(l<=mid) ans=(ans+query(root*2,l,r))%m;
    if(r>mid) ans=(ans+query(root*2+1,l,r))%m;
    return ans;
}
signed main(){
    for(int i=1;i<=n;i++){
        cin>>a[i];
    }
    build(1,1,n);
    while(q--){
        if(op==1){
            cin>>l>>r>>x;
            update(1,l,r,x,0);
        }
        if(op==2){
            cin>>l>>r>>x;
            update(1,l,r,1,x);
        }
        if(op==3){
            cin>>l>>r;
            cout<<query(1,l,r)%m<<endl;
        }
    }
    return 0;
}

最大子树和
问：一株奇怪的花卉，上面共连有n朵花，共有n−1条枝干将花儿连在一起，并且未修剪时每朵花都不是孤立的。每朵花都有一个“美丽指数”，该数越大说明这朵花越漂亮，也有“美丽指数”为负数的，求最大“美丽指数”。
第一行一个整数n(1≤n≤16000)。表示原始的那株花卉上共n朵花。
第二行有n个整数，第i个整数表示第i朵花的美丽指数。
接下来n−1行每行两个整数a,b，表示存在一条连接第a朵花和第b朵花的枝条。
输出一个数，表示一系列“修剪”之后所能得到的“美丽指数”之和的最大值。
const int INF=1e18;
int n,u,v,ans=-INF;
int a[N],dp[N];
vector <int> G[N];
void dfs(int u,int pa){
    dp[u]=a[u];
    for(int v:G[u]){
        if(v==pa) continue;
        dfs(v,u);
        if(dp[v]>0) dp[u]+=dp[v];
    }
    ans=max(ans,dp[u]);
}
signed main(){
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>a[i];
    }
    for(int i=1;i<n;i++){
        cin>>u>>v;
        G[u].push_back(v);
        G[v].push_back(u);
    }
    dfs(1,0);
    cout<<ans;
    return 0;
}

没有上司的舞会
问：现在有个周年庆宴会，宴会每邀请来一个职员都会增加一定的快乐指数 a[i]，但是呢，如果某个职员的直接上司来参加舞会了，那么这个职员就无论如何也不肯来参加舞会了。
输入的第一行是一个整数 n。
第2到第(n+1)行,每行一个整数,第(i+1)行的整数表示i号职员的快乐指数 a[i]。
第(n+2)到第2n行，每行输入一对整数v,u，代表u是v的直接上司。
int n,u,v,s;
int a[N],in[N];
int dp[N][2];
vector <int> G[N];
void dfs(int u,int pa){
    dp[u][1]=a[u];
    for(int v:G[u]){
        if(v==pa) continue;
        dfs(v,u);
        dp[u][0]+=max(dp[v][0],dp[v][1]);
        dp[u][1]+=dp[v][0];
    }
}
signed main(){
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>a[i];
    }
    for(int i=1;i<n;i++){
        cin>>v>>u;
        G[u].push_back(v);
        in[v]++;
    }
    for(int i=1;i<=n;i++){
        if(in[i]==0){
            s=i;
        }
    }
    dfs(s,0);
    cout<<max(dp[s][0],dp[s][1]);
    return 0;
}

树的最长直径/次长直径
int n,u,v,w,l,r,MaxLen=0,SeLen=0,lSeLen=0,rSeLen=0;
vector <pii> G[N];
void dfs(int u,int pa,int len){
    if(len>MaxLen){
        SeLen=MaxLen;
        MaxLen=len;
        l=u;
    }
    else if(len>SeLen){
        SeLen=len;
    }
    for(auto g:G[u]){
        int v=g.first,w=g.second;
        if(v==pa) continue;
        dfs(v,u,len+w);
    }
}
signed main(){
    cin>>n;
    for(int i=1;i<n;i++){
        cin>>u>>v>>w;
        G[u].push_back({v,w});
        G[v].push_back({u,w});
    }
dfs(1,0,0);
    r=l;
    l=0;
    MaxLen=0;
dfs(r,0,0);//最长直径
    rSeLen=SeLen;
    MaxLen=0;
    SeLen=0;
dfs(l,0,0);
lSeLen=SeLen;
    cout<<MaxLen<<" "<<max(lSeLen,rSeLen);
    return 0;
}

点权重心
问：第一行包含整数n，表示树的结点数。接下来n-1行，每行包含两个整数a和b，表示点a和点b之间存在一条无向边。输出一个整数，表示将重心删除后，剩余各个连通块中点数的最大值。
[重心定义：重心是指树中的一个结点，如果将这个点删除后，剩余各个连通块中点数的最大值最小，那么这个节点被称为树的重心]
int n,u,v,ans=1e9;
int dp[N];
vector <int> G[N];
void dfs(int u,int pa){
    dp[u]=1;
    int sum=0;
    for(int v:G[u]){
        if(v==pa) continue;
        dfs(v,u);
        dp[u]+=dp[v];
        sum=max(sum,dp[v]);
    }
    sum=max(sum,n-dp[u]);
    ans=min(ans,sum);
}
signed main(){
    cin>>n;
    for(int i=1;i<n;i++){
        cin>>u>>v;
        G[u].push_back(v);
        G[v].push_back(u);
    }
    dfs(1,0);
    cout<<ans<<endl;
    return 0;
}

边权重心
int n,u,v,w,ans=1e18,total=0;
int dp[N];
vector <pii> G[N];
void dfs(int u,int pa){
    dp[u]=0;
    int sum=0;
    for(auto g:G[u]){
        int v=g.first,w=g.second;
        if(v==pa) continue;
        dfs(v,u);
        dp[u]+=dp[v]+w;
        sum=max(sum,dp[v]+w);
    }
    sum=max(sum,total-dp[u]);
    ans=min(ans,sum);
}
signed main(){
    cin>>n;
    for(int i=1;i<n;i++){
        cin>>u>>v>>w;
        G[u].push_back({v,w});
        G[v].push_back({u,w});
        total+=w;
    }
    dfs(1,0);
    cout<<ans<<endl;
    return 0;
}
